#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// Emits docs/site/lib/generated/related-graph.ts from the shared link-graph
// builder (scripts/seo/link-graph.mjs) so the docs site can score "Related"
// links against real inbound counts at build time. Wired into prebuild /
// predev / pretest next to lab-manifest.
//
// Usage: node scripts/gen-related-graph.mjs

import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { buildLinkGraph } from "../../../scripts/seo/link-graph.mjs";

const HERE = path.dirname(fileURLToPath(import.meta.url));
const SITE_ROOT = path.resolve(HERE, "..");
const REPO_ROOT = path.resolve(SITE_ROOT, "../..");
const OUT_FILE = path.join(SITE_ROOT, "lib/generated/related-graph.ts");

const { pages } = buildLinkGraph({
	contentDir: path.join(REPO_ROOT, "docs/site/content"),
});

const data = {
	pages: {},
	out: {},
};
for (const page of [...pages.values()].sort((a, b) => a.url.localeCompare(b.url))) {
	data.pages[page.url] = { title: page.title, inbound: page.inbound };
	data.out[page.url] = [...page.out].sort();
}

const body = `// AUTO-GENERATED by docs/site/scripts/gen-related-graph.mjs - do not edit.
// Internal link graph over docs/site/content, built by scripts/seo/link-graph.mjs.
// Feeds lib/related-pages.ts (Related block) and the SEO audits in docs/audits.

export type RelatedGraphData = {
	pages: Record<string, { title: string; inbound: number }>;
	out: Record<string, string[]>;
};

export const RELATED_GRAPH: RelatedGraphData = ${JSON.stringify(data, null, 2)};
`;

fs.mkdirSync(path.dirname(OUT_FILE), { recursive: true });
fs.writeFileSync(OUT_FILE, body);
console.log(
	`related-graph: ${Object.keys(data.pages).length} pages -> ${path.relative(REPO_ROOT, OUT_FILE)}`,
);
